/**
 * One scenario per check of compliance-calendar-build-standard, for Plant Watch.
 *
 * Generated by `npx @aipathway/conformance init compliance-calendar-build-standard`,
 * then written for an Australian builder working in Queensland, New South
 * Wales and Victoria, with its own plant: an elevating work platform, a
 * scissor lift, height safety harnesses, site power tools and leads under test
 * and tag, and a registered item renewed with the state WHS regulator.
 *
 * THE FIXTURES ARE ILLUSTRATIVE. The intervals below exercise the build; they
 * are not a statement of what any Australian Standard, WHS regulator or
 * manufacturer sets. The business keeps its own rule set, with a citation on
 * each version. (The stub counts a month as 30 days.)
 *
 * Every holds() reads the trace (world.calls), never the build's return value,
 * and returns a strict boolean. Each was run against a do-nothing build and
 * against deliberately broken builds before the committed run, and goes red
 * for them (see README.md and broken/).
 */

import { CalendarWorld } from "@aipathway/conformance";

const DAY = 86_400_000;
const NOW = new Date("2026-09-21T00:00:00.000Z");

/* ---------------- fixtures ---------------- */

/** Plant items, each based in the state where it works. */
const ITEMS = [
  { id: "ewp-qld-01", tag: "EWP-01", assetClass: "system", jurisdiction: "QLD" },
  { id: "ewp-vic-02", tag: "EWP-02", assetClass: "system", jurisdiction: "VIC" },
  { id: "lift-nsw-03", tag: "SL-03", assetClass: "system", jurisdiction: "NSW" },
  { id: "harness-qld-04", tag: "HS-04", assetClass: "portable", jurisdiction: "QLD" },
  { id: "tools-nsw-05", tag: "TT-05", assetClass: "portable", jurisdiction: "NSW" },
];

const rule = (obligationType, jurisdiction, version, effectiveFrom, intervalMonths, extra = {}) => ({
  obligationType,
  jurisdiction,
  version,
  effectiveFrom,
  intervalMonths,
  retentionYears: 5,
  attestedBy: "the competent person who did the check",
  leadDays: 28,
  citation: "the business's own plant inspection rule set (illustrative)",
  ...extra,
});

/** An inspection obligation on an item, with the item's state mirrored as the register stores it. */
const ob = (id, itemId, obligationType, extra = {}) => ({
  id,
  assetId: itemId,
  obligationType,
  jurisdiction: ITEMS.find((i) => i.id === itemId).jurisdiction,
  item: ITEMS.find((i) => i.id === itemId).tag,
  owner: "Dan (yard and plant manager)",
  ...extra,
});

const world = (rules, obligations, now = NOW) =>
  Object.assign(new CalendarWorld({ now, assets: ITEMS, rules, obligations }), { marks: [] });

/* ---------------- trace helpers ---------------- */

async function run(build, w, inbox) {
  w.marks.push(w.calls.length);
  await build(w.ports(), inbox);
}

const callsOf = (w, n) =>
  n === undefined ? w.calls : w.calls.slice(w.marks[n] ?? 0, w.marks[n + 1] ?? w.calls.length);

const raised = (w, reason, id, n) =>
  callsOf(w, n).some(
    (c) => c.port === "escalate" && c.request?.reason === reason && String(c.request?.detail ?? "").startsWith(`${id};`),
  );
const raisedAny = (w, id, n) =>
  callsOf(w, n).some((c) => c.port === "escalate" && String(c.request?.detail ?? "").startsWith(`${id};`));
const prepared = (w, id, n) => callsOf(w, n).some((c) => c.port === "issue_notice" && c.request?.prepare === id);
const issued = (w, n) => callsOf(w, n).some((c) => c.port === "issue_notice" && c.response?.issued === true);
const dueReads = (w, id, n) =>
  callsOf(w, n).filter((c) => c.port === "read_rule" && c.request?.dueDate === id && c.response);
const versionReads = (w, n) => callsOf(w, n).filter((c) => c.port === "read_rule" && c.request?.obligationType);
const overdueIn = (w, id, n) =>
  callsOf(w, n).filter((c) => c.port === "gate" && c.request?.sweep).at(-1)?.response?.breached?.includes(id) === true;
const completes = (w, id, n) => callsOf(w, n).filter((c) => c.port === "evidence" && c.request?.complete === id);

const describe = (w) =>
  `${w.calls.length} port call(s) over ${w.marks.length} run(s): ` +
  w.calls.map((c) => `${c.port}:${JSON.stringify(c.request)}`).slice(0, 14).join(" | ");

/* ---------------- scenarios ---------------- */

export const scenarios = [
  {
    checkId: "dates-derived-not-stored",
    // The Queensland boom lift's annual inspection was filed on 10 February.
    // Under the first rule version it is not due until next February, so no
    // reminder goes. A new version from 1 October shortens the cycle to eight
    // months (illustrative); on the next morning's run the same item is inside
    // its lead time, so the reminder must go and the inspector booking be
    // drafted. A build that kept the first due date carries on regardless.
    world: () =>
      world(
        [
          rule("ewp-major-inspection", "QLD", "QLD-EWP-2024", "2024-01-01T00:00:00.000Z", 12, { booking: "booking request to the EWP inspector" }),
          rule("ewp-major-inspection", "QLD", "QLD-EWP-2026-10", "2026-10-01T00:00:00.000Z", 8, { booking: "booking request to the EWP inspector" }),
        ],
        [ob("ob-ewp-qld", "ewp-qld-01", "ewp-major-inspection", { anchorDate: "2026-02-10T00:00:00.000Z" })],
      ),
    drive: async (build, w) => {
      await run(build, w);
      w.advance(12 * DAY);
      await run(build, w);
    },
    holds: (w) => {
      const before = dueReads(w, "ob-ewp-qld", 0).at(-1)?.response;
      const after = dueReads(w, "ob-ewp-qld", 1).at(-1)?.response;
      return (
        before?.version === "QLD-EWP-2024" &&
        after?.version === "QLD-EWP-2026-10" &&
        before.date !== after.date &&
        !raised(w, "plant.inspection_due", "ob-ewp-qld", 0) &&
        !prepared(w, "ob-ewp-qld", 0) &&
        raised(w, "plant.inspection_due", "ob-ewp-qld", 1) &&
        prepared(w, "ob-ewp-qld", 1)
      );
    },
    describe,
  },
  {
    checkId: "superseded-versions-retained",
    // The NSW scissor lift's history says it fell due in 2025 under the old
    // six-monthly version, which has since been superseded. That past date
    // must still be explained by the retained version. A second item's history
    // names a version the rule store has never held: that one is raised.
    world: () =>
      world(
        [
          rule("scissor-lift-inspection", "NSW", "NSW-SL-2023", "2023-03-01T00:00:00.000Z", 6),
          rule("scissor-lift-inspection", "NSW", "NSW-SL-2026", "2026-01-01T00:00:00.000Z", 12),
        ],
        [
          ob("ob-lift-nsw", "lift-nsw-03", "scissor-lift-inspection", {
            anchorDate: "2026-06-01T00:00:00.000Z",
            history: [{ date: "2025-06-01T00:00:00.000Z", version: "NSW-SL-2023" }],
          }),
          ob("ob-tools-nsw", "tools-nsw-05", "scissor-lift-inspection", {
            anchorDate: "2026-06-01T00:00:00.000Z",
            history: [{ date: "2025-04-01T00:00:00.000Z", version: "NSW-SL-2019-NEVER-HELD" }],
          }),
        ],
      ),
    drive: async (build, w) => {
      await run(build, w);
    },
    holds: (w) => {
      const read = versionReads(w).find((c) => c.request.obligationType === "scissor-lift-inspection" && c.request.jurisdiction === "NSW");
      const versions = read?.response?.versions ?? [];
      const old = versions.find((v) => v.version === "NSW-SL-2023");
      return (
        versions.length === 2 &&
        old?.effectiveFrom === "2023-03-01T00:00:00.000Z" &&
        dueReads(w, "ob-lift-nsw").at(-1)?.response?.version === "NSW-SL-2026" &&
        !raised(w, "plant.history_unexplained", "ob-lift-nsw") &&
        raised(w, "plant.history_unexplained", "ob-tools-nsw")
      );
    },
    describe,
  },
  {
    checkId: "rules-per-jurisdiction",
    // The same check on two boom lifts, one in Queensland and one in Victoria,
    // both last inspected on 1 April. The Queensland rule (illustrative) runs
    // six months, so that lift is inside its lead time; the Victorian rule runs
    // twelve, so that one is not. One rule store, two answers.
    world: () =>
      world(
        [
          rule("ewp-periodic-inspection", "QLD", "QLD-EWPP-2025", "2025-01-01T00:00:00.000Z", 6),
          rule("ewp-periodic-inspection", "VIC", "VIC-EWPP-2025", "2025-01-01T00:00:00.000Z", 12),
        ],
        [
          ob("ob-ewp-q", "ewp-qld-01", "ewp-periodic-inspection", { anchorDate: "2026-04-01T00:00:00.000Z" }),
          ob("ob-ewp-v", "ewp-vic-02", "ewp-periodic-inspection", { anchorDate: "2026-04-01T00:00:00.000Z" }),
        ],
      ),
    drive: async (build, w) => {
      await run(build, w);
    },
    holds: (w) => {
      const q = dueReads(w, "ob-ewp-q").at(-1)?.response;
      const v = dueReads(w, "ob-ewp-v").at(-1)?.response;
      return (
        q?.version === "QLD-EWPP-2025" &&
        v?.version === "VIC-EWPP-2025" &&
        q.date !== v.date &&
        raised(w, "plant.inspection_due", "ob-ewp-q") &&
        !raised(w, "plant.inspection_due", "ob-ewp-v") &&
        !raised(w, "plant.inspection_overdue", "ob-ewp-v")
      );
    },
    describe,
  },
  {
    checkId: "unknown-anchor-surfaces",
    // A harness bought second hand came with no record of its last check. It
    // must surface as unknown, to a named person, with no due date reminder,
    // no booking and nothing that assumes today. The tested tools beside it,
    // with a known date, go on as normal.
    world: () =>
      world(
        [
          rule("harness-inspection", "QLD", "QLD-HS-2025", "2025-01-01T00:00:00.000Z", 6, { booking: "booking request to the height safety tester" }),
          rule("test-and-tag", "NSW", "NSW-TT-2025", "2025-01-01T00:00:00.000Z", 3),
        ],
        [
          ob("ob-harness", "harness-qld-04", "harness-inspection"),
          ob("ob-tools", "tools-nsw-05", "test-and-tag", { anchorDate: "2026-07-15T00:00:00.000Z" }),
        ],
      ),
    drive: async (build, w) => {
      await run(build, w);
    },
    holds: (w) =>
      w.calls.some((c) => c.port === "evidence" && c.request?.unknownAnchor === "ob-harness") &&
      raised(w, "plant.last_check_unknown", "ob-harness") &&
      !raised(w, "plant.inspection_due", "ob-harness") &&
      !raised(w, "plant.inspection_overdue", "ob-harness") &&
      !prepared(w, "ob-harness") &&
      !completes(w, "ob-harness").length &&
      raised(w, "plant.inspection_due", "ob-tools"),
    describe,
  },
  {
    checkId: "evidence-of-completion",
    // Two items inside their lead time. The leads and tools come back with the
    // tester's record attached: filed on the item, read back, counted done. The
    // harness comes back as "done" with nothing attached: refused, raised, and
    // still due, so its reminder goes again this run.
    world: () =>
      world(
        [
          rule("test-and-tag", "NSW", "NSW-TT-2025", "2025-01-01T00:00:00.000Z", 3),
          rule("harness-inspection", "QLD", "QLD-HS-2025", "2025-01-01T00:00:00.000Z", 6),
        ],
        [
          ob("ob-tt", "tools-nsw-05", "test-and-tag", { anchorDate: "2026-07-01T00:00:00.000Z" }),
          ob("ob-hs", "harness-qld-04", "harness-inspection", { anchorDate: "2026-04-01T00:00:00.000Z" }),
        ],
      ),
    drive: async (build, w) => {
      await run(build, w, [
        { kind: "filed", obligationId: "ob-tt", messageId: "doc-tt-118", documentRef: "doc-tt-118/test-and-tag-register.pdf" },
        { kind: "filed", obligationId: "ob-hs", messageId: "doc-hs-119" },
      ]);
    },
    holds: (w) =>
      completes(w, "ob-tt").some((c) => c.response?.accepted === true && c.request?.evidenceRef === "doc-tt-118/test-and-tag-register.pdf") &&
      !raised(w, "plant.inspection_due", "ob-tt") &&
      !raised(w, "plant.report_not_read_back", "ob-tt") &&
      completes(w, "ob-hs").some((c) => c.response?.accepted === false) &&
      !completes(w, "ob-hs").some((c) => c.response?.accepted === true) &&
      raised(w, "plant.done_without_report", "ob-hs") &&
      raised(w, "plant.inspection_due", "ob-hs"),
    describe,
  },
  {
    checkId: "refusal-is-dated-outcome",
    // The scissor lift is due. The owner decides to park it in the yard rather
    // than pay for the inspection. That is stored with its date and author, and
    // the obligation stays live: once the due date passes the item is overdue
    // and the reminder keeps going.
    world: () =>
      world(
        [rule("scissor-lift-inspection", "NSW", "NSW-SL-2026", "2026-01-01T00:00:00.000Z", 12)],
        [ob("ob-sl", "lift-nsw-03", "scissor-lift-inspection", { anchorDate: "2025-10-05T00:00:00.000Z" })],
      ),
    drive: async (build, w) => {
      await run(build, w, [{ kind: "parked", obligationId: "ob-sl", by: "Mel (owner)", at: "2026-09-21T00:00:00.000Z" }]);
      w.advance(30 * DAY);
      await run(build, w);
    },
    holds: (w) =>
      callsOf(w, 0).some((c) => c.port === "evidence" && c.request?.refusal === "ob-sl" && c.request?.at === "2026-09-21T00:00:00.000Z") &&
      raised(w, "plant.inspection_declined", "ob-sl", 0) &&
      completes(w, "ob-sl").length === 0 &&
      !overdueIn(w, "ob-sl", 0) &&
      overdueIn(w, "ob-sl", 1) &&
      raised(w, "plant.inspection_overdue", "ob-sl", 1),
    describe,
  },
  {
    checkId: "notice-needs-a-person",
    // The Victorian boom lift is overdue and its rule names a booking with the
    // inspector. The booking is drafted and held. A release with no named
    // person is refused. Nothing is issued, and the harness with no booking
    // rule gets no draft.
    world: () =>
      world(
        [
          rule("ewp-major-inspection", "VIC", "VIC-EWP-2024", "2024-01-01T00:00:00.000Z", 12, { booking: "booking request to the EWP inspector" }),
          rule("harness-inspection", "QLD", "QLD-HS-2025", "2025-01-01T00:00:00.000Z", 6),
        ],
        [
          ob("ob-ewp-vic", "ewp-vic-02", "ewp-major-inspection", { anchorDate: "2025-08-01T00:00:00.000Z" }),
          ob("ob-hs-far", "harness-qld-04", "harness-inspection", { anchorDate: "2026-08-20T00:00:00.000Z" }),
        ],
      ),
    drive: async (build, w) => {
      await run(build, w);
      await run(build, w, [{ kind: "release", obligationId: "ob-ewp-vic" }]);
    },
    holds: (w) =>
      overdueIn(w, "ob-ewp-vic", 0) &&
      prepared(w, "ob-ewp-vic", 0) &&
      raised(w, "plant.booking_drafted_awaiting_release", "ob-ewp-vic", 0) &&
      callsOf(w, 1).some((c) => c.port === "issue_notice" && c.request?.release === "ob-ewp-vic" && c.response?.issued === false) &&
      raised(w, "plant.release_refused", "ob-ewp-vic", 1) &&
      !issued(w) &&
      !prepared(w, "ob-hs-far") &&
      !raisedAny(w, "ob-hs-far"),
    describe,
  },
  {
    checkId: "breach-does-not-self-clear",
    // The NSW test and tag ran over. The first run sees it overdue and raises
    // it. A week later the tester's record arrives and is filed. A month on,
    // the register still says it went overdue, and no overdue reminder goes:
    // the next cycle starts clean, the history stays.
    world: () =>
      world(
        [rule("test-and-tag", "NSW", "NSW-TT-2025", "2025-01-01T00:00:00.000Z", 3)],
        [ob("ob-tt-late", "tools-nsw-05", "test-and-tag", { anchorDate: "2026-05-20T00:00:00.000Z" })],
      ),
    drive: async (build, w) => {
      await run(build, w);
      w.advance(7 * DAY);
      await run(build, w, [{ kind: "filed", obligationId: "ob-tt-late", messageId: "doc-tt-207", documentRef: "doc-tt-207/test-and-tag-register.pdf" }]);
      w.advance(30 * DAY);
      await run(build, w);
    },
    holds: (w) =>
      overdueIn(w, "ob-tt-late", 0) &&
      raised(w, "plant.inspection_overdue", "ob-tt-late", 0) &&
      completes(w, "ob-tt-late", 1).some((c) => c.response?.accepted === true) &&
      overdueIn(w, "ob-tt-late", 2) &&
      !raised(w, "plant.inspection_overdue", "ob-tt-late", 2),
    describe,
  },
  {
    checkId: "survives-the-builder",
    // A precondition. The runner returns evidence_required before driving it:
    // who else can explain the build, and whose account the plant register
    // runs on, is attested by the business, not by this run.
    world: () => world([], []),
    drive: async (build, w) => {
      await run(build, w);
    },
    holds: () => false,
    describe,
  },
];

// Run only in production, which this standard does not offer yet. Written so
// the pass test is ready for the live register when its port map is published.
export const liveScenarios = [
  {
    checkId: "pass-test",
    world: () => new CalendarWorld(),
    drive: async (build, w) => {
      w.marks = [];
      await run(build, w);
    },
    holds: (w) =>
      w.calls.some((c) => c.port === "read_rule" && c.request?.dueDate) &&
      w.calls.some((c) => c.port === "gate" && c.request?.sweep) &&
      !issued(w),
    describe,
  },
];
